<script setup lang="ts">
import {computed,onBeforeUnmount,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {ElMessage,ElMessageBox} from 'element-plus'
import {useUserStore} from '@/stores/user'
import {newRequestId,partnerOptions} from '@/api/modules/partner'
import {selectionDetail,selectionRow} from '@/api/modules/partnerSelections'
import * as api from '@/api/modules/sampleManagement'
import type {SampleIdentity,SamplePage,SampleShipment,SampleShipmentInput,SampleShipmentRow,ShipmentDirection} from '@/types/sampleManagement'
import type {SelectionRow} from '@/types/partnerSelections'
import type {BusinessData} from '@/types/partner'
import SelectionReceiptDialog from '../selection/SelectionReceiptDialog.vue'
import PartnerFiles from '../PartnerFiles.vue'
import SampleShipmentActionDialog from './SampleShipmentActionDialog.vue'
const props=defineProps<{domain?:string}>(),route=useRoute(),router=useRouter(),user=useUserStore()
const data=ref<SamplePage<SampleShipment>>(),detail=ref<SampleShipment>(),keyword=ref(''),direction=ref(''),status=ref(''),page=ref(1),loading=ref(false),error=ref(''),editing=ref(false),saving=ref(false),form=ref<SampleShipmentInput>(),editingId=ref<number>(),dirty=ref(false),qtyTexts=ref<Record<string,string>>({}),qtyErrors=ref<Record<string,string>>({}),identities=ref<SampleIdentity[]>([]),suppliers=ref<{code:string;name:string}[]>([]),receivers=ref<{id:number;name:string}[]>([]),action=ref<'dispatched'|'tracking'|'receive'|'loss'>(),refs=ref<BusinessData[]>([])
const uniformQty=ref('')
function applyUniformQuantity(){if(!/^[1-9]\d*$/.test(uniformQty.value)||!Number.isSafeInteger(Number(uniformQty.value))){error.value='统一拟寄数量请输入正整数';return}for(const row of form.value?.rows||[])updatePlannedQuantity(row,uniformQty.value);error.value=''}
const receipt=ref<{id:number;version:number;rows:SelectionRow[];shipmentId:number}>()
const canWrite=computed(()=>user.hasPermission('samples:write')),states:Record<string,string>={draft:'草稿',dispatched:'已实际寄出',partially_received:'部分签收',received:'已收齐',cancelled:'已取消'}
let epoch=0,detailEpoch=0,editorEpoch=0,disposed=false,seeded='';const deleteRequests=new Map<number,string>()
async function load(){const ticket=++epoch,auth=user.token;loading.value=true;error.value='';try{const result=await api.sampleShipments({page:page.value,size:50,keyword:keyword.value.trim(),direction:direction.value||undefined,status:status.value||undefined,domain:props.domain||undefined});if(ticket===epoch&&auth===user.token)data.value=result}catch(e){if(ticket===epoch&&auth===user.token)error.value=e instanceof Error?e.message:'物流记录读取失败'}finally{if(ticket===epoch)loading.value=false}}
async function open(row:SampleShipment){return openId(row.id)}
async function openId(id:number){const ticket=++detailEpoch,auth=user.token;loading.value=true;try{const value=await api.sampleShipment(id);if(ticket===detailEpoch&&auth===user.token){detail.value=value;refs.value=[];if(Number(route.query.shipmentId)!==value.id)void router.replace({path:route.path,query:{...route.query,shipmentId:value.id}})}}catch(e){if(auth===user.token)error.value=e instanceof Error?e.message:'读取寄样详情失败'}finally{if(ticket===detailEpoch)loading.value=false}}
async function searchIdentities(keyword=''){const auth=user.token;try{const result=await api.sampleIdentities({keyword,page:1,size:50,domain:props.domain||undefined});if(auth===user.token)identities.value=result.content}catch(e){if(auth===user.token)error.value=e instanceof Error?e.message:'样品码候选读取失败'}}
async function identityChanged(row:SampleShipmentRow){if(!row.sampleIdentityId)return;const auth=user.token;try{const identity=await api.sampleIdentity(row.sampleIdentityId);if(auth!==user.token)return;identities.value=[identity,...identities.value.filter(i=>i.sampleIdentityId!==identity.sampleIdentityId)];Object.assign(row,{sampleCode:identity.sampleCode,name:identity.name,specName:identity.specName,location:undefined,batchId:undefined});dirty.value=true}catch(e){error.value=e instanceof Error?e.message:'读取样品余额失败'}}
const positions=(row:SampleShipmentRow)=>{const i=identities.value.find(i=>i.sampleIdentityId===row.sampleIdentityId);return(i?.positions||i?.balances.positions||[]).filter(p=>p.available>0)}
function addRow(){const row={rowId:newRequestId(),qty:null};form.value?.rows.push(row);qtyTexts.value[row.rowId]='';dirty.value=true}
function updatePlannedQuantity(row:SampleShipmentRow,value:string){qtyTexts.value[row.rowId]=value;const text=value.trim();if(!text){row.qty=null;delete qtyErrors.value[row.rowId]}else if(/^[1-9]\d*$/.test(text)&&Number.isSafeInteger(Number(text))){row.qty=Number(text);delete qtyErrors.value[row.rowId]}else{row.qty=null;qtyErrors.value[row.rowId]='请输入正整数，未知可留空'}dirty.value=true}
function resetQuantities(){qtyTexts.value=Object.fromEntries((form.value?.rows||[]).map(row=>[row.rowId,row.qty==null?'':String(row.qty)]));qtyErrors.value={}}
async function create(kind:ShipmentDirection){if(saving.value)return;const ticket=++editorEpoch,auth=user.token;++detailEpoch;form.value={requestId:newRequestId(),direction:kind,domain:(props.domain||undefined) as SampleShipmentInput['domain'],name:kind==='mexico_outbound'?'样品发往墨西哥':'供应商寄样',origin:'',destination:kind==='mexico_outbound'?'墨西哥':'',receiverName:'',rows:[]};editingId.value=undefined;editing.value=true;dirty.value=false;error.value='';if(kind==='mexico_outbound'){await searchIdentities();if(ticket!==editorEpoch||auth!==user.token||!editing.value)return;const ids=[...new Set([Number(route.query.sampleIdentityId),...String(route.query.sampleIdentityIds||'').split(',').map(Number)].filter(id=>Number.isSafeInteger(id)&&id>0))];if(ids.length>100){error.value='一次最多选择100种样品';return}if(ids.length){try{const sources=await Promise.all(ids.map(id=>api.sampleIdentity(id)));if(ticket!==editorEpoch||auth!==user.token||!form.value||!editing.value)return;identities.value=[...sources,...identities.value.filter(i=>!ids.includes(i.sampleIdentityId))];form.value.rows=sources.map(i=>{const p=(i.positions||i.balances.positions||[]).filter(p=>p.available>0);return{rowId:newRequestId(),sampleIdentityId:i.sampleIdentityId,sampleCode:i.sampleCode,name:i.name,specName:i.specName,qty:null,location:p.length===1?p[0]!.name:undefined}});form.value.name='样品发往墨西哥 · '+sources.length+'种样品'}catch(e){if(auth===user.token&&ticket===editorEpoch)error.value=e instanceof Error?e.message:'所选样品读取失败，请重试';return}}}else{const selectionId=Number(route.query.selectionId),rowIds=String(route.query.selectionRowIds||'').split(',').filter(Boolean);if(selectionId&&rowIds.length){const head=await selectionDetail(selectionId),rows=await Promise.all(rowIds.map(id=>selectionRow(selectionId,id)));if(auth!==user.token||ticket!==editorEpoch||!form.value||!editing.value)return;form.value.selectionId=selectionId;form.value.name=head.name+' · 供应商寄样';form.value.supplierCode=rows[0]?.supplierCode;form.value.rows=rows.map(r=>({rowId:newRequestId(),selectionRowId:r.rowId,name:r.name,specName:r.modelText,qty:null}));}else addRow()}if(ticket!==editorEpoch||auth!==user.token)return;resetQuantities();dirty.value=false}
async function edit(){if(!detail.value||saving.value)return;++editorEpoch;const row=detail.value;editingId.value=row.id;form.value={requestId:newRequestId(),version:row.version,direction:row.direction,name:row.name,domain:row.domain,selectionId:row.selectionId,supplierCode:row.supplierCode,receiverUserId:row.receiverUserId,receiverName:row.receiverName,origin:row.origin,destination:row.destination,rows:row.rows.map(r=>({...r}))};editing.value=true;resetQuantities();dirty.value=false;await searchIdentities()}
async function closeEditor(){if(saving.value)return;if(dirty.value)try{await ElMessageBox.confirm('放弃尚未保存的寄样草稿？','保留填写',{confirmButtonText:'放弃',cancelButtonText:'继续填写'})}catch{return}editing.value=false;++editorEpoch;await clearSeed()}
async function clearSeed(id?:number){const query={...route.query};for(const key of ['newShipment','sampleIdentityId','sampleIdentityIds','selectionId','selectionRowIds'])delete query[key];if(id)query.shipmentId=String(id);await router.replace({path:route.path,query})}
function closeDetail(){detail.value=undefined;const query={...route.query};delete query.shipmentId;void router.replace({path:route.path,query})}
async function save(){if(!form.value)return;if(form.value.rows.some(row=>qtyErrors.value[row.rowId])){error.value='请检查拟寄数量；未知数量可以留空';return}const auth=user.token;saving.value=true;error.value='';try{const value=await api.saveSampleShipment(form.value,editingId.value);if(disposed||auth!==user.token)return;dirty.value=false;editing.value=false;detail.value=value;await clearSeed(value.id);await load();ElMessage.success('寄样草稿已保存')}catch(e){if(auth===user.token)error.value=e instanceof Error?e.message:'保存失败，原填写保留'}finally{saving.value=false}}
async function remove(){if(!detail.value)return;const current=detail.value,auth=user.token;try{const {value}=await ElMessageBox.prompt('请填写删除错建草稿的原因','删除寄样草稿',{inputValidator:value=>!!value?.trim()||'请填写原因'});const request=deleteRequests.get(current.id)||newRequestId();deleteRequests.set(current.id,request);await api.deleteSampleShipment(current.id,{version:current.version,requestId:request,reason:value.trim()});if(auth!==user.token)return;deleteRequests.delete(current.id);closeDetail();await load();ElMessage.success('草稿已删除')}catch(e){if(auth===user.token&&e!=='cancel'&&e!=='close')error.value=e instanceof Error?e.message:'删除失败'}}
async function receiveInbound(){if(!detail.value)return;const value=detail.value,context=value.receiptContext,auth=user.token;if(!context?.selectionId){error.value='此寄入记录缺少明确选品来源，请先补充来源后登记实收。';return}try{const head=await selectionDetail(context.selectionId),ids=[...new Set(context.rows.map(r=>r.selectionRowId))],rows=await Promise.all(ids.map(id=>selectionRow(context.selectionId,id)));if(auth===user.token)receipt.value={id:head.id,version:head.version,rows,shipmentId:value.id}}catch(e){error.value=e instanceof Error?e.message:'实收来源读取失败'}}
async function receiptSaved(){receipt.value=undefined;if(detail.value)await open(detail.value);await load()}
async function actionSaved(value:SampleShipment){action.value=undefined;detail.value=value;await load()}
async function refreshFiles(){if(detail.value)await open(detail.value)}
watch(()=>route.query.shipmentId,value=>{const id=Number(value);if(id>0&&detail.value?.id!==id)void openId(id)},{immediate:true})
watch([direction,status],()=>{page.value=1;void load()})
watch(()=>[props.domain,route.query.newShipment,route.query.sampleIdentityId,route.query.sampleIdentityIds,route.query.selectionId,route.query.selectionRowIds],async()=>{void load();const kind=String(route.query.newShipment||'');if(['supplier_inbound','mexico_outbound'].includes(kind)&&seeded!==route.fullPath&&canWrite.value){seeded=route.fullPath;await create(kind as ShipmentDirection)}},{immediate:true})
const eventNames:Record<string,string>={create:'建立寄样草稿',save:'保存寄样草稿',dispatched:'实际寄出',dispatch:'实际寄出',tracking:'人工物流节点',receive:'实际签收',loss:'核实短少／丢失',cancel:'取消寄样',file_add:'上传凭证',sample_shipment_create:'建立寄样草稿',sample_shipment_save:'保存寄样草稿',sample_shipment_dispatched:'实际寄出',sample_shipment_tracking:'人工物流节点',sample_shipment_receive:'实际签收',sample_shipment_loss:'核实短少／丢失',sample_shipment_cancel:'取消寄样',sample_shipment_delete:'删除寄样草稿',sample_inbound_receive:'国内实际收样'}
const optionsAuth=user.token
void api.sampleShipmentOptions().then(value=>{if(!disposed&&optionsAuth===user.token)receivers.value=value.receivers}).catch(()=>{})
void partnerOptions().then(value=>{if(!disposed&&optionsAuth===user.token)suppliers.value=value.suppliers.map(s=>({code:String(s.code),name:String(s.name)}))}).catch(()=>{})
watch(()=>user.token,()=>{++epoch;++detailEpoch;++editorEpoch;data.value=undefined;detail.value=undefined;form.value=undefined;editing.value=false;action.value=undefined;receipt.value=undefined;identities.value=[];suppliers.value=[];receivers.value=[];refs.value=[];error.value=''})
onBeforeUnmount(()=>{disposed=true;++epoch;++detailEpoch;++editorEpoch})
</script>
<template><section class="sample-shipments"><header><el-select v-model="direction" size="small" clearable placeholder="全部方向"><el-option value="supplier_inbound" label="供应商寄入"/><el-option value="mexico_outbound" label="发往墨西哥"/></el-select><el-select v-model="status" size="small" clearable placeholder="全部状态"><el-option v-for="(label,key) in states" :key="key" :value="key" :label="label"/></el-select><el-input v-model="keyword" size="small" clearable placeholder="搜索寄样单、样品或运单" @keyup.enter="page=1;load()"/><el-button size="small" @click="page=1;load()">查询</el-button><div class="shipment-tools"><el-button v-if="canWrite" size="small" @click="router.push({path:'/partner-selections',query:{from:route.fullPath}})">从选品目录登记寄样</el-button><el-button v-if="canWrite" type="primary" size="small" @click="create('mexico_outbound')">新建发墨草稿</el-button></div></header><el-alert v-if="error" :title="error" type="error" :closable="false"><el-button link @click="load">重试</el-button></el-alert><div class="shipment-list" v-loading="loading"><article v-for="row in data?.content" :key="row.id" class="shipment-row"><div><button @click="open(row)">{{row.code}}</button><strong>{{row.name}}</strong><small>{{row.direction==='supplier_inbound'?'供应商寄入':'发往墨西哥'}} · {{states[row.status]}}</small></div><div>{{row.origin||'寄出地点待补'}} → {{row.destination||'收货地点待补'}}<small>接收人 {{row.receiverName||'待确认'}} · {{row.dispatch?.tracking||'尚未登记运单'}}</small></div><div>寄出 {{row.totals.dispatched}} · 完好实收 {{row.totals.receivedGood}}<small>损坏 {{row.totals.receivedDamaged}} · 短少 {{row.totals.confirmedLoss}} · 在途 {{row.totals.inTransit}}</small></div><el-button link type="primary" size="small" @click="open(row)">查看／办理</el-button></article><el-empty v-if="data&&!data.content.length" description="暂无寄样物流记录"/></div><footer><span>物流节点按实际人工登记。</span><el-pagination v-model:current-page="page" :page-size="50" :total="data?.totalElements||0" :pager-count="5" size="small" layout="total,prev,pager,next" @current-change="load"/></footer>
<el-drawer :model-value="!!detail" :title="detail?.code+' · 寄样物流'" size="min(920px,96vw)" @close="closeDetail"><div v-if="detail" class="shipment-detail"><div class="detail-buttons"><template v-if="canWrite"><el-button v-if="detail.status==='draft'" size="small" @click="edit">编辑草稿</el-button><el-button v-if="detail.status==='draft'" size="small" type="danger" plain @click="remove">删除草稿</el-button><el-button v-if="detail.status==='draft'" size="small" type="primary" @click="action='dispatched'">登记实际寄出</el-button><template v-if="['dispatched','partially_received'].includes(detail.status)"><el-button size="small" @click="action='tracking'">记录物流节点</el-button><el-button v-if="detail.direction==='supplier_inbound'" size="small" type="primary" @click="receiveInbound">登记国内实际收样</el-button><el-button v-else size="small" type="primary" @click="action='receive'">登记实际签收</el-button><el-button size="small" @click="action='loss'">确认在途短少</el-button></template></template></div><h3>{{detail.name}} · {{states[detail.status]}}</h3><p>{{detail.origin}} → {{detail.destination}} · {{detail.receiverName||'接收人待确认'}}</p><p>{{detail.dispatch?.date||'尚未实际寄出'}} · {{detail.dispatch?.carrier}} · {{detail.dispatch?.tracking}}</p><div v-for="row in detail.rows" :key="row.rowId" class="detail-line"><strong>{{row.sampleCode||row.name}} · {{row.specName}}</strong><span>拟寄 {{(detail.status==='draft'?row.qty:row.plannedQty)??'未填'}} · 实际寄出 {{detail.status==='draft'?'尚未寄出':(row.qty??'待核对')}} 件<template v-if="row.location"> · 取出位置 {{row.location}}</template><small v-if="row.receivedBatches?.length">已实收主码 {{[...new Set(row.receivedBatches.map(batch=>batch.sampleCode))].join(' / ')}}</small><small>完好实收 {{row.receivedGood??0}} · 损坏 {{row.receivedDamaged??0}} · 短少 {{row.confirmedLoss??0}} · 剩余在途 {{row.inTransit??'待核对'}}</small></span></div><PartnerFiles kind="sample-shipments" :id="detail.id" :files="detail.files||[]" v-model="refs" :can-write="canWrite" :can-write-money="false" compact @changed="refreshFiles"/><h3>实际流转记录</h3><article v-for="event in detail.events||[]" :key="event.id" class="shipment-event"><strong>{{eventNames[event.action]||'业务记录'}} · {{event.time}}</strong><p>{{event.data?.date}} {{event.data?.tracking}} {{event.data?.note||event.data?.reason}}</p></article></div></el-drawer>
<el-dialog class="sample-shipment-editor" v-model="editing" :title="editingId?'编辑寄样草稿':'新建寄样草稿'" width="min(840px,96vw)" append-to-body :close-on-click-modal="false" :before-close="closeEditor"><el-form v-if="form" class="shipment-form" label-position="top" :disabled="saving" @input="dirty=true" @change="dirty=true"><el-form-item label="方向"><strong>{{form.direction==='supplier_inbound'?'供应商寄入':'发往墨西哥'}}</strong></el-form-item><details class="shipment-extra"><summary>更多信息（选填）</summary><el-form-item label="寄样单标题（自动生成，可修改）"><el-input v-model="form.name" placeholder="例如：10月样品发往墨西哥"/><small>用于区分这一票包裹；样品名称和样品码沿用原记录。</small></el-form-item></details><el-form-item v-if="form.direction==='supplier_inbound'" label="供应商"><el-select v-model="form.supplierCode" filterable clearable><el-option v-for="s in suppliers" :key="s.code" :value="s.code" :label="s.name"/></el-select></el-form-item><el-form-item label="寄出地点（简单填写）"><el-input v-model="form.origin"/></el-form-item><el-form-item label="目的地（简单填写）"><el-input v-model="form.destination"/></el-form-item><el-form-item label="接收人"><el-input v-model="form.receiverName"/></el-form-item><el-form-item v-if="form.direction==='mexico_outbound'" label="系统签收账号（选填）"><el-select v-model="form.receiverUserId" filterable clearable placeholder="按姓名选择真实接收账号"><el-option v-for="person in receivers" :key="person.id" :value="person.id" :label="person.name"/></el-select><small>分配后，该账号可扫码办理本人包裹；无系统账号仍可填写上方实际接收人。</small></el-form-item><div v-if="form.rows.length>1" class="uniform-quantity"><el-input v-model="uniformQty" inputmode="numeric" placeholder="统一拟寄数量（每种）" aria-label="每种拟寄数量"/><el-button @click="applyUniformQuantity">应用到全部 {{form.rows.length}} 项</el-button></div><div v-for="(row,index) in form.rows" :key="row.rowId" class="draft-row"><el-form-item label="样品"><strong v-if="row.selectionRowId">{{row.name}} · {{row.specName}}</strong><template v-else><div v-if="row.sampleIdentityId" class="sample-choice-summary"><strong>{{row.sampleCode}} · {{row.name}}</strong><small>{{row.specName}}</small></div><details :open="!row.sampleIdentityId"><summary>{{row.sampleIdentityId?'更换样品':'选择样品'}}</summary><el-select v-model="row.sampleIdentityId" filterable remote :remote-method="searchIdentities" clearable placeholder="搜索已有样品码" @change="identityChanged(row)"><el-option v-for="i in identities" :key="i.sampleIdentityId" :value="i.sampleIdentityId" :label="i.sampleCode+' · '+i.name+' · '+i.specName+' · 可用 '+i.balances.available"/></el-select></details></template></el-form-item><el-form-item label="拟寄数量（未知留空）" :error="qtyErrors[row.rowId]"><el-input :model-value="qtyTexts[row.rowId]||''" inputmode="numeric" placeholder="未知留空" :aria-label="'拟寄数量 '+row.rowId" @update:model-value="(value:string)=>updatePlannedQuantity(row,value)"/></el-form-item><el-form-item v-if="form.direction==='mexico_outbound'" label="从哪个现有位置取出"><el-select v-model="row.location" clearable placeholder="选择实际取出位置"><el-option v-for="p in positions(row)" :key="p.name" :value="p.name" :label="p.name+' · 可用 '+p.available"/></el-select></el-form-item><el-button link type="danger" @click="form.rows.splice(index,1);dirty=true">移除此项</el-button></div><el-button link @click="addRow">＋ 添加样品</el-button><p>草稿不改变库存；实际寄出和实收另按本次数量办理。</p></el-form><el-alert v-if="error" :title="error" type="error" :closable="false"/><template #footer><el-button @click="closeEditor">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存草稿</el-button></template></el-dialog>
<SampleShipmentActionDialog v-if="detail&&action" :shipment="detail" :action="action" :refs="refs" @close="action=undefined" @saved="actionSaved"/>
<SelectionReceiptDialog v-if="receipt" :id="receipt.id" :version="receipt.version" :rows="receipt.rows" :from="route.fullPath" :supplier-shipment-id="receipt.shipmentId" @close="receipt=undefined" @saved="receiptSaved"/>
</section></template>
